mapper.select:
SELECT 
FROM ai_business_process p

WHERE p.tenant_id = #{tenantId}
  AND p.application_id = #{applicationId}
  AND p.del_flag = 0

  AND (
    p.process_code LIKE CONCAT('%', #{keyword}, '%')
    OR p.process_name LIKE CONCAT('%', #{keyword}, '%')
    OR p.process_description LIKE CONCAT('%', #{keyword}, '%')
  )


  AND p.status = #{status}


  AND p.design_status = #{designStatus}

ORDER BY p.update_time DESC, p.id DESC

SELECT 
FROM ai_business_process p

WHERE p.tenant_id = #{tenantId}
  AND p.id = #{id}
  AND p.del_flag = 0
LIMIT 1

SELECT 
FROM ai_business_process p

WHERE p.tenant_id = #{tenantId}
  AND p.application_id = #{applicationId}
  AND p.process_code = #{processCode}
  AND p.del_flag = 0
LIMIT 1

mapper.update:
UPDATE ai_business_process
SET draft_schema_json = #{schemaJson},
    draft_schema_hash = #{schemaHash},
    design_status = #{designStatus},
    update_by = #{updateBy},
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND id = #{id}
  AND del_flag = 0
  AND draft_schema_hash = #{expectedSchemaHash}
